namespace Jeninnet.Validation.OpenApi.NSwag;

/// <summary>
/// Applies Jeninnet.Validation constraints to schemas generated by NSwag/NJsonSchema.
/// </summary>
/// <param name="registry">The descriptor registry.</param>
public sealed class JeninnetValidationSchemaProcessor(ValidationSchemaRegistry registry) : ISchemaProcessor {
    private readonly ValidationSchemaRegistry _registry =
        registry ?? throw new ArgumentNullException(nameof(registry));

    /// <summary>
    /// Applies the constraints for the type currently being generated. Referenced schemas are
    /// skipped because the processor runs again for the schema definition they point to.
    /// </summary>
    /// <param name="context">The schema processor context.</param>
    /// <exception cref="ArgumentNullException"><paramref name="context"/> is null.</exception>
    public void Process(SchemaProcessorContext context) {
        ArgumentNullException.ThrowIfNull(context);

        if(context.Schema.HasReference || context.Schema.Properties is not { Count: > 0 } properties) {
            return;
        }

        var modelType = context.ContextualType.OriginalType;

        if(modelType is null || !_registry.TryGet(modelType, out var descriptor) || descriptor is null) {
            return;
        }

        foreach(var member in descriptor.Members) {
            var constraints = ValidationSchemaMapper.MapMember(member);
            var propertyName = SchemaPropertyNameResolver.Resolve(modelType, properties.Keys, member.Name);

            if(propertyName is null || !properties.TryGetValue(propertyName, out var property)) {
                continue;
            }

            if(property.HasReference) {
                continue;
            }

            NJsonSchemaConstraintWriter.Apply(constraints, property);

            if(IsRequired(constraints)) {
                context.Schema.RequiredProperties.Add(propertyName);
            }
        }
    }

    private static bool IsRequired(ValidationSchemaConstraints constraints) {
        if(!constraints.IsRequired) {
            return false;
        }

        var memberType = constraints.MemberType;
        if(memberType is null) {
            return true;
        }

        return Nullable.GetUnderlyingType(memberType) is not null || !memberType.IsValueType;
    }
}
